INSERT INTO `products` VALUES (502,'',NULL,'2026-08-20 09:05:37.503780','',_binary '',_binary '','Sanitary Stainless Steel Centrifugal Pump',NULL,'http://localhost:8080/uploads/products/87d6027b-9bf9-43bb-9777-90c9a6e12e71.jpeg','Hygienic stainless steel centrifugal pump for dairy, beverage, food and pharmaceutical liquid transfer.','sanitary-stainless-steel-centrifugal-pump',1,'PUBLISHED','2026-08-20 09:08:40.647536',4,'[\"Dairy Plants\",\"Commercial Kitchen\"]','MADE_TO_ORDER','Nandhas','India','2–3 Weeks',18.00,'Free On-Site Commissioning',_binary '',_binary '',_binary '','Nandhas Engineering Works',1,'','2200 × 1400 × 1850 mm','QUOTE_ONLY','Machinery','850 KG','4–6 Weeks','','','','Pan-India On-Site Support','NAND-SCP-01',NULL,10,'','','','1 Year Comprehensive Warranty'),(503,'',NULL,'2026-08-20 09:15:53.093741','',_binary '',_binary '','Skid-Mounted Commercial Microbrewery Brewhouse System (2-Vessel Architecture)',NULL,'http://localhost:8080/uploads/products/25d21a37-4332-436a-bf77-fce0a78f5a7c.jpeg','Compact skid-mounted 2-vessel brewhouse system for craft breweries, taprooms, brewpubs and pilot-scale beer production.','skid-mounted-commercial-microbrewery-brewhouse-system-2-vessel',2,'PUBLISHED','2026-08-20 09:17:34.382926',3,'[\"Dairy Plants\",\"Commercial Kitchen\"]','MADE_TO_ORDER','Nandhas','India','2–3 Weeks',18.00,'Free On-Site Commissioning',_binary '',_binary '',_binary '','Nandhas Engineering Works',1,'','2200 × 1400 × 1850 mm','QUOTE_ONLY','Machinery','850 KG','4–6 Weeks','','','','Pan-India On-Site Support','NAND-MBH-2V',NULL,10,'','','','1 Year Comprehensive Warranty'),(504,NULL,NULL,'2026-08-20 10:46:43.068374','<h3>Product Overview</h3><p>The Nandhas Sanitary Stainless Steel Centrifugal Pump is designed for clean, dependable product transfer in dairy, beverage, food and pharmaceutical processing lines. Its smooth stainless steel construction, crevice-minimised hygienic design and sanitary connections make it suitable for frequent cleaning and washdown environments.</p><h4>Key Product Benefits</h4><ul><li>SS316L product-contact components available for demanding hygienic applications.</li><li>Sanitary Tri-Clamp inlet and outlet connections for quick installation and maintenance.</li><li>High-efficiency closed impeller design for steady, low-pulsation transfer.</li><li>Mechanical seal options selected for the product temperature and process duty.</li><li>Configured to order for the required flow, head, motor power and connection size.</li></ul><p><strong>Important:</strong> Final pump selection should be confirmed against the required flow rate, delivery head, liquid temperature, viscosity and CIP duty.</p>',_binary '',_binary '','Sanitary Stainless Steel Centrifugal Pump',NULL,'/uploads/products/sanitary-stainless-steel-centrifugal-pump.jpg','Hygienic stainless steel centrifugal pump for reliable transfer of milk, beverages and low-to-medium viscosity food liquids.','sanitary-stainless-steel-centrifugal-pump-nand-scp-01',1,'PUBLISHED','2026-08-20 10:46:43.071582',4,'[\"Dairy Processing Plants\",\"Milk and Cream Transfer\",\"Beverage Processing Lines\",\"Food and Sauce Processing\",\"CIP and Sanitary Piping Systems\",\"Pharmaceutical Liquid Transfer\"]','MADE_TO_ORDER','Nandhas','India','3-5 Weeks Pan-India',18.00,'Commissioning support available on request',_binary '',_binary '',_binary '','Nandhas Engineering Works',1,'SCP-01','Approx. 700 x 500 x 600 mm, depending on model','QUOTE_ONLY','Machinery','Approx. 35-95 KG, depending on configuration','3-5 Weeks','Hygienic SS316L centrifugal pump for dairy, beverage, food and pharmaceutical liquid transfer. Request a configured quote from Nandhas.','sanitary centrifugal pump, stainless steel dairy pump, SS316L food pump, Tri-Clamp pump, hygienic process pump','Sanitary Stainless Steel Centrifugal Pump | Nandhas','Pan India','NAND-SCP-01',NULL,0,NULL,NULL,NULL,'1 Year Comprehensive Warranty'),(505,NULL,55200.00,'2026-08-20 10:46:43.336961','<h3>Product Overview</h3><p>Essential milk reception dump tank with sanitary top filtration sieve and bottom butterfly valve drain.</p><h4>Key Engineering Highlights</h4><ul><li>Constructed using certified food-grade SS304 Food Grade with sanitary mirror interior polish.</li><li>Equipped with high-efficiency 0.5 HP Pump (Optional) motor and heavy-duty planetary/gearbox transmission.</li><li>Sanitary crevice-free Argon TIG welding meeting strict FSSAI & ISO hygiene standards.</li><li>Supplied with full 1-Year Comprehensive Warranty and factory on-site commissioning across India.</li></ul>',_binary '\0',_binary '\0','Commercial Milk Dump Tank 200L Single Compartment',48000.00,'https://images.unsplash.com/photo-1527153857715-3908f2ae5e81?auto=format&fit=crop&w=800&q=80','Commercial Milk Dump Tank 200L Single Compartment engineered by Nandhas Engineering Works for high-throughput commercial processing. Built with certified SS304 Food Grade.','commercial-milk-dump-tank-200l-single-compartment-nand-mdt-200',2,'PUBLISHED','2026-08-20 10:46:43.336961',1,'[\"Dairy Plants\",\"Milk Collection Centers\",\"Paneer Factories\",\"Commercial Dairies\"]','IN_STOCK','Nandhas','India','7-10 Days Pan-India',18.00,'Free Installation & Commissioning',_binary '',_binary '',_binary '','Nandhas Engineering Works',1,'MDT200',NULL,'STARTING_FROM','Machinery','120 KG - 1500 KG','1-2 Weeks',NULL,NULL,NULL,'Pan India','NAND-MDT-200',48000.00,15,NULL,NULL,NULL,'1 Year Comprehensive On-Site Warranty'),(506,NULL,74750.00,'2026-08-20 10:46:43.465962','<h3>Product Overview</h3><p>Stainless steel milk reception weigh bowl with dual-mesh filtration tray and rapid discharge valve.</p><h4>Key Engineering Highlights</h4><ul><li>Constructed using certified food-grade SS304 Food Grade with sanitary mirror interior polish.</li><li>Equipped with high-efficiency 1.0 HP Sanitary Pump motor and heavy-duty planetary/gearbox transmission.</li><li>Sanitary crevice-free Argon TIG welding meeting strict FSSAI & ISO hygien